    ctx.hooks = {
      onRequest: vi.fn(),
      onError: vi.fn(),
      onResponse: vi.fn(),
    };

    ctx.errors = [];
    ctx.hooks.onError.mockImplementation((error, _event: H3Event) => {
      if (opts.debug) {
        console.error(error);
      }
      ctx.errors.push(error);
    });

    ctx.app = new H3({
      debug: true,
      onError: ctx.hooks.onError,
      onRequest: ctx.hooks.onRequest,
      onResponse: ctx.hooks.onResponse,
      plugins: [opts.tracing ? tracingPlugin() : undefined].filter((p) => !!p),
    });
  });

  afterEach(async () => {
    const errors = ctx.errors;

    ctx.app = undefined!;
    ctx.hooks = undefined!;
    ctx.errors = undefined!;

    vi.resetAllMocks();
    if (!opts.allowUnhandledErrors) {
      const unhandledErrors = errors.filter((error) => error.unhandled);
      if (unhandledErrors.length > 0) {
        throw mergeErrors(errors);
      }
    }
  });

  return ctx;
}

// --- types ---

export interface TestOptions {
  allowUnhandledErrors?: boolean;
  startServer?: boolean;
  debug?: boolean;
  tracing?: boolean;

