  describe("extraUnsealPasswords", () => {
    const passA = "A".repeat(48);
    const passB = "B".repeat(48);
    const passC = "C".repeat(48);
    const legacySealOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };
    const config: SessionConfig = {
      name: "h3-extra",
      password: passA,
      extraUnsealPasswords: [passB],
    };

    function sealedCookie(res: Response, name: string): string | undefined {
      const setCookie = res.headers.getSetCookie().find((c) => c.startsWith(`${name}=`));
      return setCookie && decodeURIComponent(setCookie.slice(name.length + 1).split(";")[0]);
    }

    // Counts PBKDF2 derivations made while `run` executes. The outcome of `run`
    // is asserted separately, so its rejection is ignored here.
    async function countDerivations(run: () => Promise<unknown>): Promise<number> {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        await run().catch(() => {});
        return deriveBits.mock.calls.length;
      } finally {
        deriveBits.mockRestore();
      }
    }

    it("seals with password only, even when extra passwords are configured", async () => {
      t.app.get("/seal-only", async (event) => {
        await updateSession(event, config, { user: "alice" });
        return "ok";
      });
      const res = await t.fetch("/seal-only");
      const sealed = sealedCookie(res, "h3-extra")!;
      expect(await unseal(sealed, passA, sealDefaults)).toMatchObject({ data: { user: "alice" } });
      await expect(unseal(sealed, passB, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("keeps the seal and PBKDF2 cost unchanged without extra passwords", async () => {
      const sealed = await seal({ id: "plain", createdAt: Date.now(), data: {} }, passA, sealDefaults);
      const noExtras: SessionConfig = { password: passA, legacySealFallback: false };
      const emptyExtras: SessionConfig = { ...noExtras, extraUnsealPasswords: [] };
      const wrong: SessionConfig = { password: passB, legacySealFallback: false };

      expect(await countDerivations(() => unsealSession({} as HTTPEvent, noExtras, sealed))).toBe(2);
      expect(await countDerivations(() => unsealSession({} as HTTPEvent, emptyExtras, sealed))).toBe(2);
      expect(await countDerivations(() => unsealSession({} as HTTPEvent, wrong, sealed))).toBe(1);
    });

    it("still rejects a short password in seal", async () => {
      t.app.get("/short", async (event) => {
        try {
          await updateSession(event, { name: "h3-short", password: "short" });
          return { rejected: false };
        } catch (error) {
          return { rejected: true, message: (error as Error).message };
        }
      });
      const body = await (await t.fetch("/short")).json();
      expect(body.rejected).toBe(true);
      expect(body.message).toMatch(/password/i);
    });

    it("tries password, then extras in order, and stops at the first that opens", async () => {
      const cfg: SessionConfig = {
        password: passA,
        extraUnsealPasswords: [passB, passC],
        legacySealFallback: false,
      };
      const sealWith = (password: string) =>
        seal({ id: "ordered", createdAt: Date.now(), data: {} }, password, sealDefaults);
      const sealedA = await sealWith(passA);
      const sealedB = await sealWith(passB);
      const sealedC = await sealWith(passC);

      expect(await countDerivations(() => unsealSession({} as HTTPEvent, cfg, sealedA))).toBe(2);
      expect(await countDerivations(() => unsealSession({} as HTTPEvent, cfg, sealedB))).toBe(3);
      expect(await countDerivations(() => unsealSession({} as HTTPEvent, cfg, sealedC))).toBe(4);
      expect(await unsealSession({} as HTTPEvent, cfg, sealedC)).toMatchObject({ id: "ordered" });
    });

    it("does not spend an extra attempt on a repeated password", async () => {
      const sealedA = await seal({ id: "dup", createdAt: Date.now(), data: {} }, passA, sealDefaults);
      const sealedC = await seal({ id: "dup", createdAt: Date.now(), data: {} }, passC, sealDefaults);
      const dupConfig: SessionConfig = {
        password: passA,
        extraUnsealPasswords: [passA],
        legacySealFallback: false,
      };
      expect(await countDerivations(() => unsealSession({} as HTTPEvent, dupConfig, sealedA))).toBe(2);

      // A repeated extra is tried once: A and B fail, then the HMAC error surfaces
      const repeated: SessionConfig = {
        password: passA,
        extraUnsealPasswords: [passB, passB],
        legacySealFallback: false,
      };
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        await expect(unsealSession({} as HTTPEvent, repeated, sealedC)).rejects.toThrow(
          "Bad hmac value",
        );
        expect(deriveBits).toHaveBeenCalledTimes(2);
      } finally {
        deriveBits.mockRestore();
      }
    });

    it.each([
      ["an empty string entry", [""]],
      ["a non-string entry", [42]],
      ["an entry shorter than the minimum", ["s".repeat(31)]],
      ["null", null],
      ["a string instead of an array", "not-an-array"],
    ])("rejects %s before creating the session", async (_label, value) => {
      t.app.get("/validate", async (event) => {
        try {
          await getSession(event, { ...config, extraUnsealPasswords: value as string[] });
          return { rejected: false };
        } catch (error) {
          return {
            rejected: true,
            message: (error as Error).message,
            sessionCreated: event.context.sessions !== undefined,
          };
        }
      });
      const body = await (await t.fetch("/validate")).json();
      expect(body.rejected).toBe(true);
      expect(body.message).toContain("extraUnsealPasswords");
      expect(body.sessionCreated).toBe(false);
    });

    it("accepts an extra password at the minimum length", async () => {
      t.app.get("/minimum", async (event) => {
        const session = await getSession(event, {
          ...config,
          extraUnsealPasswords: ["m".repeat(32)],
        });
        return { id: session.id };
      });
      const body = await (await t.fetch("/minimum")).json();
      expect(body.id).toBeTruthy();
    });

    it("reseals a session opened with an extra password on the same request", async () => {
      const createdAt = Date.now() - 1000;
      const old = await seal({ id: "old", createdAt, data: { user: "bob" } }, passB, sealDefaults);
      t.app.get("/reseal", async (event) => {
        const session = await getSession(event, config);
        return {
          id: session.id,
          createdAt: session.createdAt,
          data: session.data,
          symbols: Object.getOwnPropertySymbols(session).map((s) => s.description),
        };
      });

      const res = await t.fetch("/reseal", { headers: { Cookie: `h3-extra=${old}` } });
      const body = await res.json();
      expect(body).toMatchObject({ id: "old", createdAt, data: { user: "bob" } });
      expect(body.symbols).not.toContain("h3.internal.session.previous-password-seal");

      const resealed = sealedCookie(res, "h3-extra");
      expect(resealed).toBeDefined();
      expect(await unseal(resealed!, passA, sealDefaults)).toMatchObject({
        id: "old",
        createdAt,
        data: { user: "bob" },
      });
      await expect(unseal(resealed!, passB, sealDefaults)).rejects.toThrow("Bad hmac value");

      // The resealed cookie opens with `password`, so the next read does not reseal
      const res2 = await t.fetch("/reseal", {
        headers: { Cookie: `h3-extra=${encodeURIComponent(resealed!)}` },
      });
      expect(await res2.json()).toMatchObject({ id: "old", data: { user: "bob" } });
      expect(res2.headers.getSetCookie()).toHaveLength(0);
    });

    it("opens a header session sealed with an extra password without resealing it", async () => {
      const sealed = await seal(
        { id: "hdr", createdAt: Date.now(), data: { user: "carol" } },
        passB,
        sealDefaults,
      );
      const headerConfig: SessionConfig = { ...config, name: "h3-hdr" };
      t.app.get("/header", async (event) => {
        const session = await getSession(event, headerConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/header", { headers: { "x-h3-hdr-session": sealed } });
      expect(await res.json()).toMatchObject({ id: "hdr", data: { user: "carol" } });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("unseals, marks and reseals a legacy seal made with an extra password", async () => {
      const legacy = await seal(
        { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
        passB,
        legacySealOptions,
      );
      t.app.get("/legacy", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/legacy", { headers: { Cookie: `h3-extra=${legacy}` } });
      expect(await res.json()).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
      const resealed = sealedCookie(res, "h3-extra");
      expect(resealed).toBeDefined();
      expect(await unseal(resealed!, passA, sealDefaults)).toMatchObject({ id: "legacy" });
    });

    it("rejects a legacy seal made with an extra password when legacySealFallback is false", async () => {
      const legacy = await seal(
        { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
        passB,
        legacySealOptions,
      );
      t.app.get("/legacy-strict", async (event) => {
        const session = await useSession(event, { ...config, legacySealFallback: false });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/legacy-strict", { headers: { Cookie: `h3-extra=${legacy}` } });
      const body = await res.json();
      expect(body.id).not.toBe("legacy");
      expect(body.data).toEqual({});
    });

    it("fails an expired seal made with an extra password without trying other passwords", async () => {
      const expired = await seal({ id: "old", createdAt: Date.now(), data: {} }, passB, {
        ...sealDefaults,
        ttl: -120_000,
      });
      expect(await countDerivations(() => unsealSession({} as HTTPEvent, config, expired))).toBe(0);
      await expect(unsealSession({} as HTTPEvent, config, expired)).rejects.toThrow("Expired seal");
    });

    it("starts a new session when maxAge has passed for a session opened with an extra password", async () => {
      const old = await seal(
        { id: "old", createdAt: Date.now() - 2 * 3600_000, data: {} },
        passB,
        sealDefaults,
      );
      t.app.get("/max-age", async (event) => {
        const session = await useSession(event, { ...config, maxAge: 3600 });
        return { id: session.id };
      });

      const res = await t.fetch("/max-age", { headers: { Cookie: `h3-extra=${old}` } });
      expect((await res.json()).id).not.toBe("old");
    });

    it("invalidates only the seals made with a removed extra password", async () => {
      const withPrevious = await seal({ id: "removed", createdAt: Date.now(), data: {} }, passC, sealDefaults);
      const withKept = await seal({ id: "kept", createdAt: Date.now(), data: {} }, passB, sealDefaults);
      // passC is no longer configured; passB still is
      const current: SessionConfig = { ...config, extraUnsealPasswords: [passB] };
      t.app.get("/remove", async (event) => {
        const session = await useSession(event, current);
        return { id: session.id };
      });

      const removed = await t.fetch("/remove", { headers: { Cookie: `h3-extra=${withPrevious}` } });
      expect((await removed.json()).id).not.toBe("removed");

      const kept = await t.fetch("/remove", { headers: { Cookie: `h3-extra=${withKept}` } });
      expect((await kept.json()).id).toBe("kept");
    });
  });
});

